def sudoku_valid(board):
    """Return True if no row, column, or 3x3 box repeats a non-zero digit.

    The board may be incomplete (0 means empty) and need not be solvable.
    Raises ValueError if the board is not 9x9 or holds a value outside 0..9.
    """
    # --- shape validation -------------------------------------------------
    if not isinstance(board, (list, tuple)) or len(board) != 9:
        raise ValueError("board must be a 9x9 grid")
    for row in board:
        if not isinstance(row, (list, tuple)) or len(row) != 9:
            raise ValueError("board must be a 9x9 grid")

    # --- value validation -------------------------------------------------
    for row in board:
        for value in row:
            if isinstance(value, bool) or not isinstance(value, int):
                raise ValueError("board values must be integers 0..9")
            if value < 0 or value > 9:
                raise ValueError("board values must be integers 0..9")

    # --- duplicate checks -------------------------------------------------
    rows = [set() for _ in range(9)]
    cols = [set() for _ in range(9)]
    boxes = [set() for _ in range(9)]

    for r in range(9):
        for c in range(9):
            v = board[r][c]
            if v == 0:
                continue
            b = (r // 3) * 3 + (c // 3)
            if v in rows[r] or v in cols[c] or v in boxes[b]:
                return False
            rows[r].add(v)
            cols[c].add(v)
            boxes[b].add(v)

    return True
```

Shape and value checks run first so an invalid board always raises before any duplicate scanning; the main loop then tracks seen digits per row, column, and box in one pass.
